
/* =============== 5.2 flashcards & mnemonics =============== */
const PARTN={1:"Part 1 · The disease",2:"Part 2 · Diagnosis",3:"Part 3 · Treatment",4:"Part 4 · Crisis, care & the future",5:"Part 5 · History"};
const FC=[
 [1, "What is myasthenia gravis (MG)?", "An autoimmune disease of the neuromuscular junction. Antibodies against the acetylcholine receptor (AChR), MuSK or other receptor-related proteins on the muscle side of the junction cause fluctuating, fatigable weakness."],
 [1, "How common is MG?", "Estimates differ more than twofold. A 2021 meta-analysis of 63 studies gave a global prevalence of 12.4 per 100,000; MedlinePlus says about 20 per 100,000. Prevalence has risen in recent decades, mainly in older people."],
 [1, "How do age and sex shape who gets MG?", "Before 40, women outnumber men about 3:1. In the 40s the sexes are equal; after 50 men slightly predominate (3:2). Incidence in women peaks around 30 and 50; in men it rises with age and is highest at 60-89."],
 [1, "What separates early-onset from late-onset MG?", "Age at onset: before 50 is early-onset, 50 or later is late-onset. A 2026 meta-analysis proposes splitting the older group at 65 (very-late-onset)."],
 [1, "What share of people with MG have AChR antibodies?", "About 80% of all MG, and about 85% of generalized MG."],
 [1, "What is MuSK-MG?", "MG with antibodies to muscle-specific kinase: about 7-10% of all MG. Up to 85% of patients are women. Over 40% present with bulbar weakness, often with neck and breathing involvement."],
 [1, "What is the most common first symptom of MG?", "Eye symptoms: asymmetric drooping eyelid (ptosis) and double vision. About two-thirds start this way; in a Japanese series ptosis was the first symptom in 74.9%."],
 [1, "Which things stay normal in MG?", "Pupils, sensation and tendon reflexes. The weakness is painless."],
 [1, "How often does ocular MG become generalized?", "Older cohorts: up to 80% of adults, usually within 2 years. A US population-based study: 55%, at a median of 13 months. Of people still purely ocular after 2 years, about 90% stay ocular."],
 [1, "How often are thymoma and MG linked?", "Thymoma is present in about 10-20% of people with MG, and about 30-44% of people with thymoma have or develop MG."],
 [1, "How many acetylcholine molecules are in one quantum, and how many quanta does a human nerve impulse release?", "About 10,000 ACh molecules per quantum. A human junction releases only about 20-30 quanta per impulse, the fewest known among vertebrates studied (mouse 50-100)."],
 [1, "What is the safety factor at the neuromuscular junction?", "The margin by which transmitter release exceeds what is needed to fire the muscle fibre: normally 2-4 times (3-5 in another review). In one human study it fell from 2.98 in controls to 1.09 in MG."],
 [1, "Where do the AChRs and the sodium channels sit on the postsynaptic membrane?", "AChRs pack the crests of the junctional folds at about 10,000 per square micrometre, held by rapsyn. Voltage-gated sodium channels (NaV1.4) fill the troughs and start the muscle action potential."],
 [1, "What are the three ways AChR antibodies damage the junction?", "1) Complement: IgG1/IgG3 trigger the classical pathway and the membrane attack complex (C5b-9) destroys the folds. 2) Antigenic modulation: cross-linked receptors are degraded faster (about threefold in one study). 3) Direct blocking of the receptor, a minority mechanism."],
 [1, "Why do MuSK antibodies cause weakness without complement?", "They are mainly IgG4, which does not activate complement. After Fab-arm exchange they are functionally monovalent and block MuSK from binding LRP4, so agrin can no longer keep AChRs clustered."],
 [1, "Which signalling chain builds and maintains AChR clusters?", "Nerve agrin binds LRP4, which activates MuSK. MuSK signals through Dok-7, and rapsyn tethers the AChRs into dense clusters."],
 [1, "Why does weakness grow with repeated use in MG?", "During a train of impulses the readily releasable vesicle store empties, so each impulse releases fewer quanta. Healthy junctions absorb this with their safety factor; in MG more and more endplate potentials fall below threshold and fibres drop out."],
 [1, "How common is fatigue, as distinct from muscle fatigability?", "About 60% in large registry studies, linked to disease severity, depression and physical inactivity."],
 [2, "How sensitive is the AChR binding antibody test?", "Abnormal in up to about 85% of adults with generalized MG but only about 50% of ocular MG. Specificity is 95-100%; sensitivity is nearly 100% in thymoma-associated MG."],
 [2, "If AChR antibodies are negative, what comes next?", "MuSK antibodies. In double-seronegative patients, LRP4 and clustered-AChR cell-based assays can follow, alongside electrodiagnosis."],
 [2, "What does the clustered-AChR cell-based assay add?", "It detects AChR antibodies missed by the standard assay: 38.1% of RIPA-negative MG in routine Oxford practice (66% in the original research series), with 100% specificity."],
 [2, "What counts as an abnormal repetitive nerve stimulation (RNS) test for MG?", "At 2-5 Hz, a reproducible decrement of 10% or more from the 1st to the 4th or 5th response."],
 [2, "What shape does the RNS decrement take in MG?", "The biggest drop is between the 1st and 2nd responses, the low point comes at the 4th-5th, then the amplitude levels off or partly recovers: a U shape."],
 [2, "Which test is most sensitive for MG, and what is its weakness?", "Jitter on single-fibre or concentric-needle EMG: abnormal in 98-100% of generalized and over 90% of ocular MG. It is not specific: neuropathy, myopathy, motor neuron disease and botulinum toxin also raise jitter."],
 [2, "How is the ice-pack test done and how good is it?", "Ice over the drooping eyelid for 2-5 minutes; an improvement of 2 mm or more is positive. In 155 consecutive ptosis referrals: sensitivity 86%, specificity 79%."],
 [2, "Why is the edrophonium (Tensilon) test now rarely used?", "Mimics can test positive and it carries cardiac risks (bradyarrhythmia to asystole). A 2022 review notes that since 2018 it is no longer marketed in the US as a test for MG."],
 [2, "Why is the chest imaged in MG?", "To look for thymoma, found in about 10-20% of people with MG. Reviews say no clinical or antibody feature reliably excludes it, and advise CT (preferred) or MRI in all confirmed or strongly suspected MG."],
 [2, "MGFA class I and class V: what do they mean?", "Class I: any eye-muscle weakness only (eye closure may be weak), all other strength normal. Class V: intubation, with or without mechanical ventilation, except routine postoperative care."],
 [2, "What do the letters a and b mean in MGFA classes II-IV?", "a: mainly limb and axial muscles. b: mainly oropharyngeal (bulbar) and breathing muscles. A feeding tube without intubation counts as IVb."],
 [2, "What is the MG-ADL?", "An 8-item patient-reported scale, each item 0-3, total 0-24, rating the last 7 days. A 2-point improvement indicates clinical improvement."],
 [2, "What is the QMG?", "The Quantitative Myasthenia Gravis score: 13 clinician-scored items, each 0-3, total 0-39. It takes about 20-30 minutes and needs a spirometer, stopwatch and dynamometer."],
 [2, "How does Lambert-Eaton syndrome (LEMS) differ from MG on nerve tests?", "LEMS: low baseline CMAP that increases by 60-100% or more after 10 s of exercise or high-rate stimulation. MG: normal CMAP with a low-rate decrement. LEMS antibodies target P/Q calcium channels; about half of patients have small-cell lung cancer."],
 [2, "Which features point to botulism rather than MG?", "Acute, symmetric paralysis descending from the cranial nerves, in an alert, afebrile person; pupils may be dilated (37%). The edrophonium test is usually negative."],
 [2, "When should a congenital myasthenic syndrome be suspected?", "Weakness from birth or childhood, a family history, negative AChR, MuSK and LRP4 antibodies, and no improvement with immunosuppression."],
 [2, "What is minimal manifestation status (MM)?", "No symptoms of functional limitation from MG, though some weakness can be found on careful examination (MGFA wording). The 2016 consensus sets MM or better, with no more than grade 1 drug side effects, as the treatment goal."],
 [2, "What is complete stable remission?", "No symptoms or signs of MG for at least 1 year with no MG therapy during that time (isolated weakness of eye closure is accepted)."],
 [3, "How does pyridostigmine work?", "It is a reversible cholinesterase inhibitor: it slows the breakdown of acetylcholine so more of it reaches the remaining receptors. It eases symptoms; it does not act on the immune cause."],
 [3, "How long does a dose of pyridostigmine last?", "About 3-4 hours by day; a bedtime dose often lasts about 6 hours (UK product information)."],
 [3, "Why is pyridostigmine often taken 30-60 minutes before meals?", "An NHS Scotland Q&A gives a 30-60 minute onset, so the peak can fall on chewing and swallowing; no primary pharmacology study gives an onset in minutes, and no neurology guideline read sets meal timing. Food delays the plasma peak from 1.7 to 3.2 hours without reducing absorption."],
 [3, "What are pyridostigmine's muscarinic and nicotinic side effects?", "Muscarinic: nausea, vomiting, diarrhoea, abdominal cramps, salivation, bronchial secretions, small pupils, sweating. Nicotinic: muscle cramps, fasciculations and weakness."],
 [3, "How does pyridostigmine perform in MuSK-MG?", "Poorly: the consensus says people with MuSK-MG respond less and often get side effects at conventional doses."],
 [3, "What is the steroid dip?", "Transient worsening after starting corticosteroids: 21-48% across studies. No source gives a typical timing; studies counted it within 2 weeks (26%) or 4 weeks (42%). In one study it was more likely with older age, severe bulbar symptoms and more severe disease. The consensus says it may be appropriate to wait several days for PLEX or IVIG to work first."],
 [3, "How fast does azathioprine work?", "Slowly: first response after 4-10 months, peak at about 14 months. In Palace 1998 the steroid-sparing effect showed at 3 years, not at 1 year."],
 [3, "Why did the two 2008 mycophenolate trials fail?", "Prednisone worked better than expected and the trials were short (12 and 36 weeks). In a retrospective series, good outcomes began to rise only after about 6 months."],
 [3, "Which immunosuppressants are contraindicated in pregnancy?", "Mycophenolate and methotrexate (cyclophosphamide is also teratogenic). The consensus calls prednisone the immunosuppressant of choice in pregnancy."],
 [3, "IVIG or plasma exchange (PLEX)?", "The consensus calls them probably equally effective in severe generalized MG: in Barth 2011, 69% vs 65% improved by day 14. Expert consensus suggests PLEX works faster in crisis, but a meta-analysis found only a non-significant trend; PLEX may work better in MuSK-MG. The consensus says PLEX cannot be used in sepsis, and IVIG is contraindicated in hypercoagulable states, renal failure or immunoglobulin hypersensitivity."],
 [3, "What did MGTX show at 3 years?", "In 126 people with AChR+ non-thymomatous generalized MG aged 18-65, extended transsternal thymectomy plus prednisone gave a lower time-weighted QMG (6.15 vs 8.99) and less alternate-day prednisone (44 vs 60 mg) than prednisone alone. Hospitalization for exacerbation: 9% vs 37%."],
 [3, "What did the MGTX 5-year extension show?", "The gap widened: time-weighted QMG 5.47 vs 9.34, alternate-day prednisone 24 vs 48 mg, and minimal manifestation status at month 60 in 88% vs 58%."],
 [3, "For whom does current evidence not support thymectomy?", "People with MuSK, LRP4 or agrin antibody MG. The thymus is thought not to be involved in MuSK-MG."],
 [3, "How do C5 inhibitors work, and which are approved for gMG?", "They stop C5 being cleaved, so the membrane attack complex (C5b-9) cannot form, while upstream C3 stays intact. In the US: eculizumab, ravulizumab and zilucoplan, for AChR-antibody-positive gMG."],
 [3, "What is the key safety rule for C5 inhibitors?", "A boxed warning for serious meningococcal infection: vaccination against serogroups A, C, W, Y and B at least 2 weeks before the first dose (or antibiotics if treatment cannot wait), access through a REMS. Vaccination does not eliminate the risk."],
 [3, "How do FcRn blockers lower pathogenic antibodies?", "FcRn normally rescues IgG from lysosomes, giving IgG a half-life of about 19-21 days. Blocking it sends IgG, pathogenic antibodies included, to degradation. Total IgG falls by about 55-80% depending on the drug, and recovers after dosing stops."],
 [3, "How is IV efgartigimod given, and what did ADAPT show?", "10 mg/kg IV once weekly for 4 weeks is one cycle; further cycles follow clinical response. In AChR+ patients, 68% vs 30% were MG-ADL responders in cycle 1."],
 [3, "Where does rituximab have its best evidence?", "MuSK-MG: 58% vs 16% reached a favourable outcome in a blinded review (NNT 2.4). In AChR+ disease, BeatMG was futile for steroid sparing, but RINOMAX in new-onset gMG found minimal manifestations in 71% vs 29%."],
 [4, "What is myasthenic crisis?", "Worsening of MG that needs intubation, or non-invasive ventilation to avoid intubation. Difficulty breathing or swallowing is an emergency."],
 [4, "How often, and when, does crisis happen?", "15-20% of people with MG have at least one crisis, usually in the first 2-3 years. In one series the median time from first symptoms to first crisis was 8 months."],
 [4, "What triggers crisis?", "Infection most often (38% in a 73-episode series), aspiration in 10%. No trigger is found in 30-40%."],
 [4, "Myasthenic or cholinergic crisis: how do they differ?", "Cholinergic crisis comes from too much cholinesterase inhibitor: muscarinic signs (sweating, tearing, salivation, nausea, diarrhoea, slow heart) plus fasciculations. The pyridostigmine label says the two may be hard to tell apart by symptoms; the consensus says cholinergic crisis is now rare."],
 [4, "What is the single breath count?", "The person takes a deep breath and counts aloud at about 2 counts per second. A count of 25 or more fits normal breathing muscles; each number corresponded to about 116 mL of FVC."],
 [4, "Where does the 20/30/40 bedside rule come from?", "Guillain-Barré syndrome (VC 20 mL/kg, MIP 30, MEP 40 cmH2O), not MG; no MG validation of the full rule was found. In one 42-patient MG study, ventilation was unlikely when VC was over 20 mL/kg, MEP over 40 cmH2O or MIP more negative than -40 cmH2O."],
 [4, "Why can a normal pulse oximeter mislead in neuromuscular weakness?", "Oxygen saturation can stay normal while CO2 rises: in one neuromuscular audit, 54% of patients with high CO2 had saturation of 95% or more."],
 [4, "Which antibiotics carry the strongest MG warnings?", "Telithromycin is contraindicated (boxed warning; no longer marketed in the US). Fluoroquinolones carry a boxed warning for MG exacerbation (added 2011). Macrolides and aminoglycosides carry label warnings."],
 [4, "Why is magnesium sulfate a problem in MG?", "IV magnesium blocks neuromuscular transmission. The consensus does not recommend it for eclampsia in MG; barbiturates or phenytoin usually suffice."],
 [4, "Are drugs on caution lists strictly off limits?", "No. The MGFA says an association does not necessarily mean a drug should not be prescribed; some drugs may be necessary and should not be deemed off limits, with clinician supervision."],
 [4, "Why is pyridostigmine called time-critical in hospital?", "A UK safety bulletin says to give it within 30 minutes of the due time: a late dose can cause weakness or inability to swallow, and missed doses can precipitate crisis."],
 [4, "What is transient neonatal MG?", "Weakness in a baby caused by maternal IgG antibodies crossing the placenta: about 10% of babies (9-13% in pooled series). It nearly always appears in the first 24 hours and usually resolves within 4 weeks."],
 [4, "How does pregnancy affect MG?", "About 30% worsen during pregnancy, most often in the first trimester, and about 27% worsen after delivery. The first months after delivery carry the highest risk."],
 [4, "What do people with MG need to know about anaesthesia?", "They are more sensitive to non-depolarizing muscle relaxants (vecuronium ED95 about 56% of normal) and resistant to succinylcholine (up to 2.6 times the dose)."],
 [4, "Is the flu vaccine safe in MG?", "In a randomized trial of 47 AChR-MG patients, protection matched healthy controls and MG did not worsen. Guidance says live vaccines should be avoided if possible under immunosuppression."],
 [4, "How common are depression, anxiety and sleep apnoea in MG?", "Pooled prevalence: depression 36%, anxiety 33%. Obstructive sleep apnoea was found in 36%, against an expected 15-20% in the general population."],
 [4, "What is the evidence for CAR-T cell therapy in MG?", "Early evidence. Three German patients given anti-CD19 CAR-T stayed in remission off MG therapy for at least 19 months. Descartes-08 (mRNA anti-BCMA) is the only CAR-type therapy with a completed double-blind trial: 66.7% vs 27.3% responders (n=26)."],
 [4, "What are the results and risks of autologous stem cell transplant in MG?", "In 21 people with severe refractory MG, 16 of 18 evaluable (89%) reached drug-free remission, maintained over a median 6.7 years. Transplant-related mortality at 100 days was 9.5%."],
 [5, "Who gave the first recognisable description of MG?", "Thomas Willis in 1672: patients well in the morning and weak by noon, including a woman whose speech failed after long talking."],
 [5, "Who named the disease, and what else did he show?", "Friedrich Jolly in 1895: myasthenia gravis pseudoparalytica. He showed that repeated electrical stimulation made the muscle response decline, the forerunner of repetitive nerve stimulation."],
 [5, "What did Mary Walker report in 1934?", "Dramatic improvement with physostigmine (Lancet), followed in 1935 by neostigmine: the start of cholinesterase-inhibitor treatment."],
 [5, "What did Blalock report in 1939?", "Removal of a thymic tumour from a patient with MG (operation 1936). In 1941 his group reported planned thymectomy in MG without thymoma."],
 [5, "Who first proposed that MG is autoimmune?", "John Simpson (Edinburgh) in 1960: antibodies to the endplate receptor, with a role for the thymus."],
 [5, "What did the 1973 experiments establish?", "Patrick and Lindstrom immunised rabbits with purified eel AChR and caused myasthenic paralysis (EAMG). Fambrough, Drachman and Satyamurti showed fewer AChRs at MG junctions using labelled alpha-bungarotoxin."],
 [5, "What did Toyka and colleagues show in 1975?", "Passive transfer: injecting MG patients' immunoglobulin into mice reduced mEPP amplitude and AChR numbers, showing the antibody is enough to cause MG features."],
 [5, "What did Lindstrom's 1976 assay find?", "AChR antibodies in 87% of 71 MG patients and none of 175 controls, which established the diagnostic test."],
 [5, "Why did MG mortality fall from about 40% to about 5%?", "Between the early 1960s and the 1970s, mainly because of positive-pressure ventilation and intensive care units."],
 [5, "When were MuSK and LRP4 antibodies discovered?", "MuSK: Hoch and colleagues in 2001, in 70% of AChR-seronegative generalized MG. LRP4: Higuchi and colleagues in 2011."],
 [5, "What was the first randomized trial of thymectomy, and when?", "MGTX, published in 2016, about 75 years after Blalock. The 2000 AAN practice parameter and the 2013 Cochrane review had called for such a trial."],
 [5, "Which were the first complement and FcRn drugs approved for gMG in the US?", "Eculizumab on 23 October 2017 (first complement inhibitor) and efgartigimod on 17 December 2021 (first FcRn blocker), both for AChR-antibody-positive adults."]
];
const MN=[
 ["Young women, old men", "A published shorthand, not an invented one: a US hospital study called MG “still a disease of young women and old men”. Women are most often diagnosed before 40, men after 60."],
 ["10 · 1→4 · U", "<b>Study aid.</b> RNS at 2-5 Hz: a decrement of <b>10%</b> or more, compared from the <b>1st to the 4th</b> (or 5th) response, with a <b>U</b>-shaped curve (biggest drop between 1st and 2nd, then a partial recovery)."],
 ["10,000 · 20-30 · 2-4", "<b>Study aid.</b> About <b>10,000</b> ACh molecules per quantum; about <b>20-30</b> quanta per human nerve impulse; a safety factor of about <b>2-4</b> times what is needed. MG erodes that margin."],
 ["Complement, Cross-link, Cover", "<b>Study aid.</b> The three ways AChR antibodies harm the junction: <b>complement</b> lysis of the folds, <b>cross-linking</b> that speeds receptor degradation (about threefold in one study), and <b>covering</b> (blocking) the binding site, a minority route."],
 ["MuSK says no", "<b>Study aid.</b> MuSK antibodies are IgG4: <b>no</b> complement, <b>no</b> clear thymus role and <b>no</b> evidence for thymectomy, and a poor pyridostigmine response. Better results are reported with rituximab (58% vs 16% favourable outcome in a blinded review) and plasma exchange (93% improved vs 61% with IVIG in a 110-patient series)."],
 ["SLUDGE + twitch", "<b>A general pharmacology teaching mnemonic, not MG-specific.</b> Muscarinic excess: <b>S</b>alivation, <b>L</b>acrimation (tearing), <b>U</b>rinary urgency, <b>D</b>iarrhoea, <b>G</b>I cramps, <b>E</b>mesis. Add the nicotinic <b>twitch</b>: fasciculations and cramps. The pyridostigmine label's own list overlaps (salivation, diarrhoea, cramps, vomiting) and adds sweating, small pupils and bronchial secretions; it does not list tearing or urinary urgency."],
 ["C5 · ACWY + B · 2 weeks", "<b>Study aid.</b> Before a <b>C5</b> inhibitor (eculizumab, ravulizumab, zilucoplan), the labels require meningococcal vaccination against <b>A, C, W, Y and B</b> at least <b>2 weeks</b> before the first dose, or antibiotics if treatment cannot wait."],
 ["FcRn = Recycling rescue", "<b>Study aid.</b> FcRn grabs IgG in the acidic endosome and <b>recycles</b> it back to the blood, which is why IgG lasts 19-21 days. Block the <b>rescue</b> and IgG, including the pathogenic antibody, goes to the lysosome."],
 ["18-65 · AChR+ · under 5 · no thymoma", "<b>Study aid.</b> Who MGTX enrolled: age <b>18-65</b>, <b>AChR</b>-antibody positive, generalized MG for <b>under 5</b> years, and <b>no thymoma</b>. The 2020 consensus frames early thymectomy for ages 18-50."],
 ["24 · 39 · 50", "<b>Study aid.</b> Scale maxima: <b>MG-ADL 24</b> (8 items × 3), <b>QMG 39</b> (13 items × 3), <b>MG Composite 50</b> (10 weighted items). Higher is worse on all three."]
];
inits.review=()=>{
  let filt='all',deck=[],i=0;
  const F=[['all','%t:cards.all%'],...Object.keys(PARTN).map(k=>[k,'%t:part%'+k])];
  $('#fcFilter').innerHTML=F.map(([k,l])=>`<button class="btn" data-ff="${k}" aria-pressed="${k==='all'}">${l}</button>`).join('');
  const fc=$('#fc');
  function build(shuf){deck=FC.filter(c=>filt==='all'||String(c[0])===filt);if(shuf){const r=rng(Date.now()%1e6);for(let k=deck.length-1;k>0;k--){const j=Math.floor(r()*(k+1));[deck[k],deck[j]]=[deck[j],deck[k]]}}i=0;render()}
  function render(){const c=deck[i];fc.classList.remove('flip');
    $('#fcTagF').textContent=PARTN[c[0]]+'%t:cards.question%';$('#fcTagB').textContent=PARTN[c[0]]+'%t:cards.answer%';
    $('#fcFront').textContent=c[1];$('#fcBack').textContent=c[2];$('#fcCount').textContent=`${i+1}%t:cards.of%${deck.length}`;$('#fcBar').style.width=((i+1)/deck.length*100)+'%'}
  const flip=()=>fc.classList.toggle('flip');
  fc.addEventListener('click',flip);$('#fcFlip').onclick=flip;
  const next=()=>{i=(i+1)%deck.length;render()},prev=()=>{i=(i-1+deck.length)%deck.length;render()};
  $('#fcNext').onclick=next;$('#fcPrev').onclick=prev;$('#fcShuf').onclick=()=>build(true);
  $('#fcFilter').addEventListener('click',e=>{const b=e.target.closest('[data-ff]');if(!b)return;filt=b.dataset.ff;$$('[data-ff]').forEach(x=>x.setAttribute('aria-pressed',x===b));build(false)});
  document.addEventListener('keydown',e=>{if(cur!=='review')return;if(e.target.closest('input')||(e.target.closest('button')&&e.target!==fc))return;
    if(e.key===' '||e.key==='Enter'){e.preventDefault();flip()}else if(e.key==='ArrowRight')next();else if(e.key==='ArrowLeft')prev()});
  build(false);
  $('#mnList').innerHTML=MN.map(m=>`<div class="card"><b class="big">${m[0]}</b><p>${m[1]}</p></div>`).join('');
};

/* =============== 5.3 quiz =============== */
const QZ=[
 [1, "In most people with MG, the disease-causing antibodies target:", ["The acetylcholine receptor on the muscle side of the junction", "The presynaptic P/Q calcium channel", "Acetylcholinesterase in the cleft", "Myelin on the motor nerve"], 0, "About 80% of people with MG have AChR antibodies. Antibodies to the presynaptic P/Q calcium channel cause Lambert-Eaton syndrome instead."],
 [1, "Which pattern of weakness is typical of MG?", ["Weakness that worsens with use and eases with rest", "Constant weakness with muscle pain", "Numbness spreading up from the feet", "Weakness with brisk reflexes"], 0, "Fatigable, fluctuating, painless weakness, often worse later in the day. Sensation and reflexes stay normal."],
 [1, "The most common first symptom of MG is:", ["Shortness of breath", "Hand weakness", "A drooping eyelid or double vision", "Neck pain"], 2, "About two-thirds start with eye symptoms; in a Japanese series ptosis was the first symptom in 74.9%."],
 [1, "MuSK antibodies are mainly of which IgG subclass?", ["IgG1", "IgG2", "IgG3", "IgG4"], 3, "MuSK antibodies are mainly IgG4, which does not activate complement. They act by blocking the MuSK-LRP4 interaction."],
 [1, "The main way AChR antibodies destroy the endplate is by:", ["Recruiting T cells into the muscle fibre", "Activating complement, so the membrane attack complex lyses the folds", "Blocking calcium entry into the nerve terminal", "Killing the motor neuron"], 1, "IgG1 and IgG3 bound to AChR trigger the classical complement pathway; C5b-9 destroys the folds. In 30 patients, membrane attack complex stained every endplate while inflammatory cells were at under 10%."],
 [1, "Antigenic modulation means that AChR antibodies:", ["Mimic acetylcholine", "Switch fetal receptors to adult ones", "Cross-link receptors so they are internalised and degraded faster", "Make receptors larger"], 2, "Myasthenic IgG roughly tripled the AChR degradation rate; monovalent Fab, which cannot cross-link, had no effect."],
 [1, "MuSK antibodies cause weakness mainly because they:", ["Activate complement strongly", "Destroy the motor nerve", "Activate acetylcholinesterase", "Stop MuSK binding LRP4, so AChRs lose their clustering signal"], 3, "Agrin–LRP4–MuSK–Dok-7–rapsyn keeps AChRs clustered. Monovalent IgG4 blocks the MuSK–LRP4 step and AChR clusters break up."],
 [1, "About how many quanta does one human nerve impulse release?", ["2-3", "20-30", "200-300", "About 10,000"], 1, "About 20-30, the fewest known among vertebrates studied. About 10,000 is the number of ACh molecules in one quantum."],
 [1, "What happens to the neuromuscular safety factor in MG?", ["It rises, because the nerve makes more ACh", "It does not change", "It changes only in the nerve terminal", "It falls, so endplate potentials fail to reach threshold"], 3, "In human intercostal muscle it fell from 2.98 in controls to 1.09 in MG. The nerve does release more quanta in compensation, but not enough."],
 [1, "On a healthy endplate, the voltage-gated sodium channels (NaV1.4) are concentrated:", ["In the troughs of the junctional folds", "On the crests of the folds", "Only in the nerve terminal", "In the cleft basal lamina"], 0, "AChRs sit on the crests facing the nerve; NaV1.4 fills the troughs and starts the muscle action potential."],
 [1, "A person with MG asks why their eyelid droops more by evening. The best explanation is:", ["The eyelid muscle is destroyed a little each day", "Repeated use releases less transmitter per signal, and with fewer receptors more signals fail", "Daylight damages the muscle", "Their pupils are weakening"], 1, "Transmitter release runs down with repeated activity. With a reduced safety factor, more endplate potentials fall below threshold as use continues."],
 [1, "Which statement about sex and age in MG is correct?", ["It affects only older men", "Men and women are affected equally at every age", "Before 40 women outnumber men; after 50 men slightly predominate", "It affects only children"], 2, "About 3:1 female before 40, equal in the 40s, about 3:2 male after 50: young women and old men."],
 [1, "Early-onset MG is defined as onset before age:", ["30", "40", "50", "65"], 2, "Before 50 is early-onset; 50 or later is late-onset. Some authors split off very-late-onset MG at 65."],
 [1, "Of adults who still have purely ocular MG 2 years after onset, about how many stay ocular?", ["10%", "50%", "75%", "90%"], 3, "Most generalization happens within 2 years; of those still ocular at 2 years, about 90% stay ocular."],
 [1, "Thymoma is found in roughly what share of people with MG?", ["Under 1%", "About 10-20%", "About 50%", "About 80%"], 1, "About 10-20% (a 49-study review pooled 21%). Thymic hyperplasia is far more common, in about 65%."],
 [1, "Which of these is NOT affected in MG?", ["Eyelids", "Swallowing", "Neck muscles", "Pupils"], 3, "Pupils, sensation and tendon reflexes are normal in MG. Abnormal pupils point to other diagnoses such as botulism."],
 [1, "The autoimmune disease that most often coexists with MG is:", ["Autoimmune thyroid disease", "Type 1 diabetes", "Psoriasis", "Coeliac disease"], 0, "About 13% of people with MG have another autoimmune disease, most often autoimmune thyroid disease."],
 [1, "Fatigue, as distinct from muscle fatigability, affects about what share of people with MG?", ["5%", "20%", "60%", "95%"], 2, "About 60% in large registry studies, linked to severity, depression and physical inactivity."],
 [2, "Repetitive nerve stimulation is abnormal for MG when there is:", ["A reproducible decrement of 10% or more from the 1st to the 4th or 5th response at 2-5 Hz", "An increment of 100% after exercise", "A low CMAP that rises with 50 Hz stimulation", "Absent sensory responses"], 0, "That is the AAEM (2001) criterion; one review notes the 10% cut-off has never been formally validated. An increment after exercise or high-rate stimulation points to LEMS."],
 [2, "In MG the RNS decrement typically:", ["Falls steadily to the 10th response", "Appears only at 50 Hz", "Is largest between the 1st and 2nd responses, then levels off or partly recovers", "Is replaced by an increment"], 2, "Biggest drop between responses 1 and 2, low point at 4-5, then partial recovery: the U shape of a postsynaptic disorder."],
 [2, "The most sensitive test for MG is:", ["Jitter on single-fibre or concentric-needle EMG", "AChR antibody", "Low-rate RNS of a hand muscle", "Chest CT"], 0, "Jitter is abnormal in 98-100% of generalized and over 90% of ocular MG. It is not specific: neuropathy, myopathy, motor neuron disease and botulinum toxin also raise jitter."],
 [2, "Which test result is the most specific for MG?", ["Abnormal jitter", "A positive ice-pack test", "A positive AChR antibody test", "A positive edrophonium test"], 2, "AChR antibody specificity is 95-100%. Jitter has the highest sensitivity but low specificity."],
 [2, "AChR binding antibody sensitivity is lowest in:", ["Thymoma-associated MG", "Generalized MG", "Late-onset MG", "Ocular MG"], 3, "Up to about 85% in generalized MG and nearly 100% with thymoma, but only about 50% in ocular MG."],
 [2, "A positive ice-pack test is an improvement in ptosis of at least:", ["0.5 mm", "2 mm", "5 mm", "10 mm"], 1, "Ice for 2-5 minutes; 2 mm or more is positive. In 155 ptosis referrals: sensitivity 86%, specificity 79%."],
 [2, "On nerve testing, Lambert-Eaton syndrome differs from MG because LEMS shows:", ["A normal CMAP with a low-rate decrement only", "No response at all", "A low baseline CMAP that increases markedly after 10 s of exercise", "Absent sensory potentials"], 2, "With a 60% increment limit, sensitivity for LEMS was 97% and specificity versus MG 99%."],
 [2, "When AChR antibodies are negative, the usual next antibody test is:", ["Titin", "VGCC", "GQ1b", "MuSK"], 3, "MuSK is tested next; LRP4 and clustered-AChR assays follow in double-seronegative patients."],
 [2, "Chest CT or MRI is advised in MG mainly to:", ["Look for a thymoma", "Measure lung volume", "Rule out pneumonia", "Stage lung cancer"], 0, "Thymoma is found in about 10-20% of people with MG, and reviews say no clinical or antibody feature reliably excludes it."],
 [2, "MGFA class V means:", ["Ocular weakness only", "Mild generalized weakness", "Severe limb weakness", "Intubation, with or without ventilation, outside routine postoperative care"], 3, "The 2016 consensus defines manifest crisis as also including non-invasive ventilation used to avoid intubation."],
 [2, "Moderate weakness mainly of swallowing and breathing muscles is MGFA class:", ["IIa", "IIIb", "IVa", "I"], 1, "III = moderate; b = predominantly oropharyngeal or respiratory."],
 [2, "A feeding tube without intubation places a patient in MGFA class:", ["IIIb", "IVa", "IVb", "V"], 2, "The MGFA wording puts feeding tube without intubation in class IVb."],
 [2, "The MG-ADL total score ranges from:", ["0-10", "0-24", "0-39", "0-50"], 1, "8 items scored 0-3. QMG runs 0-39 and the MG Composite 0-50."],
 [2, "Which scale is clinician-administered and needs a spirometer, stopwatch and dynamometer?", ["MG-ADL", "MG-QOL15r", "Single breath count", "QMG"], 3, "The QMG has 13 items, 0-39 points, and takes about 20-30 minutes."],
 [2, "Which picture points to botulism rather than MG?", ["Fluctuating ptosis over months", "Acute symmetric descending paralysis in an alert, afebrile person, sometimes with dilated pupils", "Positive AChR antibodies", "A U-shaped RNS decrement"], 1, "Botulism descends from the cranial nerves; dilated pupils occur in 37%. The edrophonium test is usually negative."],
 [2, "The edrophonium (Tensilon) test is now rarely used, mainly because:", ["It takes too long", "It needs general anaesthesia", "It only works in MuSK-MG", "Mimics can test positive and it carries cardiac risks"], 3, "Serious events include bradyarrhythmia to asystole. A 2022 review notes that since 2018 it is no longer marketed in the US as a test for MG."],
 [2, "Which clue suggests a congenital myasthenic syndrome?", ["Onset in infancy, negative antibodies and no response to immunotherapy", "Onset at 70 with thymoma", "High AChR antibody titre", "Paralysis after home-canned food"], 0, "Other clues: family history and gene-specific drug responses."],
 [2, "Complete stable remission requires no symptoms or signs, and no MG therapy, for at least:", ["1 month", "6 months", "1 year", "5 years"], 2, "Isolated weakness of eye closure is accepted."],
 [2, "A person with MG has a high AChR antibody level but feels well. What does research say?", ["Titre correlates poorly with severity between people", "Titre predicts severity closely", "A high titre always means crisis is near", "The test is not useful for diagnosis"], 0, "Some severely weak people have low titres and some in remission have high titres, attributed to differences in antibody specificity, affinity and subclass."],
 [3, "Pyridostigmine improves strength by:", ["Slowing the breakdown of acetylcholine in the cleft", "Depleting B cells", "Blocking complement", "Replacing lost receptors"], 0, "It is a reversible cholinesterase inhibitor. It eases symptoms but does not act on the immune cause."],
 [3, "A daytime dose of pyridostigmine typically lasts about:", ["30 minutes", "3-4 hours", "12 hours", "24 hours"], 1, "About 3-4 hours by day; a bedtime dose often lasts about 6 hours."],
 [3, "An NHS Scotland Q&A times pyridostigmine 30-60 minutes before meals. What reason does it give?", ["Food destroys the drug", "It must be taken on a full stomach", "It starts working in about 30-60 minutes, so chewing and swallowing are stronger at the meal", "It causes hunger"], 2, "The Q&A gives a 30-60 minute onset; no neurology guideline read sets meal timing, and a nursing source suggests about 20 minutes for altered diets. Food delays the plasma peak (1.7 to 3.2 hours) without reducing absorption."],
 [3, "Which of these is a muscarinic side effect of pyridostigmine?", ["Diarrhoea and abdominal cramps", "Fasciculations", "Muscle cramps", "Weakness"], 0, "Fasciculations, muscle cramps and weakness are nicotinic effects. Muscarinic effects include GI upset, salivation, secretions, sweating and small pupils."],
 [3, "In MuSK-MG, pyridostigmine:", ["Often helps less and causes side effects at conventional doses", "Works better than in AChR-MG", "Cures the disease", "Is the only treatment that works"], 0, "The edrophonium or neostigmine test was equivocal or negative in 29.7% of MuSK patients, and mouse data suggest pyridostigmine can worsen anti-MuSK AChR loss."],
 [3, "Early transient worsening after starting corticosteroids has been reported in about:", ["1-2%", "21-48%", "80-90%", "100%"], 1, "Studies counted it within the first 2 weeks (26%) or 4 weeks (42%); no source gives a typical timing. The consensus says it may be appropriate to let PLEX or IVIG work first."],
 [3, "Azathioprine's first clinical response usually appears after:", ["2-3 days", "2 weeks", "4-10 months", "3 years"], 2, "Peak improvement came at about 14 months; in Palace 1998 the steroid-sparing effect showed at 3 years."],
 [3, "Before starting azathioprine, the Nordic guidance advises testing:", ["TPMT activity", "HLA-B27", "G6PD", "Vitamin D"], 0, "Low or absent TPMT activity risks severe bone-marrow toxicity; the guidance avoids azathioprine if TPMT is low."],
 [3, "Which treatment is contraindicated in pregnancy according to the consensus?", ["Prednisone", "Pyridostigmine", "Mycophenolate mofetil", "IVIG"], 2, "Mycophenolate and methotrexate are teratogenic. Prednisone is the immunosuppressant of choice in pregnancy."],
 [3, "MGTX enrolled people with:", ["Thymoma at any age", "MuSK-MG", "Purely ocular MG", "AChR+ generalized non-thymomatous MG, aged 18-65, for under 5 years"], 3, "126 people were randomized to extended transsternal thymectomy plus prednisone or prednisone alone."],
 [3, "At 3 years in MGTX, the thymectomy group had:", ["Higher QMG and more prednisone", "Lower QMG (6.15 vs 8.99) and less prednisone (44 vs 60 mg alternate days)", "No measurable difference", "More hospital admissions"], 1, "Hospitalization for exacerbation was 9% vs 37%, and azathioprine use 17% vs 48%."],
 [3, "Current evidence does not support thymectomy in:", ["MuSK antibody MG", "AChR+ generalized MG at age 30", "Thymoma", "AChR+ MG that fails immunotherapy"], 0, "The same applies to LRP4 and agrin antibody MG. With thymoma, the 2016 consensus says that, with rare exceptions, everyone with MG should have surgery."],
 [3, "Before a C5 inhibitor (eculizumab, ravulizumab, zilucoplan), the labels require:", ["A live vaccine", "TPMT testing", "Meningococcal vaccination at least 2 weeks before the first dose", "Stopping pyridostigmine"], 2, "Serogroups A, C, W, Y and B, or antibiotics if treatment cannot wait. Vaccination does not eliminate the risk."],
 [3, "FcRn blockers lower pathogenic antibodies by:", ["Killing plasma cells", "Blocking C5", "Binding acetylcholine", "Stopping IgG recycling, so IgG is degraded in lysosomes"], 3, "Without FcRn rescue, IgG falls by about 55-80% depending on the drug, and recovers after dosing stops."],
 [3, "Which statement about FcRn blockers is correct?", ["They lower IgG but not IgM or IgA, and the effect reverses", "They need meningococcal vaccination", "They are approved only for MuSK-MG", "They are given once a year"], 0, "Meningococcal vaccination is a C5-inhibitor requirement. FcRn blocker labels advise against live vaccines during treatment."],
 [3, "Which drug has the strongest evidence in MuSK-MG?", ["Rituximab", "Thymectomy", "Eculizumab", "High-dose pyridostigmine"], 0, "58% vs 16% reached a favourable outcome (NNT 2.4). Eculizumab is approved only for AChR+ gMG."],
 [3, "In Barth 2011, IVIG and plasma exchange for worsening MG were:", ["Clearly different, PLEX far better", "Both ineffective", "Clearly different, IVIG far better", "Similar: 69% vs 65% improved by day 14"], 3, "The consensus calls them probably equally effective in severe generalized MG. Expert consensus suggests PLEX acts faster in crisis, but a meta-analysis found only a non-significant trend."],
 [3, "According to the 2016 consensus, plasma exchange cannot be used in a person with:", ["Bulbar weakness", "Pregnancy", "MuSK-MG", "Sepsis"], 3, "The consensus lists hypercoagulable states, renal failure and immunoglobulin hypersensitivity as contraindications to IVIG."],
 [3, "In REGAIN, eculizumab's prespecified worst-rank primary analysis:", ["Was highly significant", "Showed harm", "Was never analysed", "Missed significance (p=0.0698), while repeated-measures analyses favoured eculizumab"], 3, "The label's repeated-measures MG-ADL difference was -1.9 at week 26. REGAIN is often cited in debates on how analysis choice shapes approval."],
 [3, "Which FcRn blocker's US label was widened in May 2026 to adults with gMG regardless of antibody status?", ["Rozanolixizumab", "Efgartigimod", "Nipocalimab", "Zilucoplan"], 1, "The May 2026 US label includes ADAPT SERON data (n=119) in AChR-negative patients. Zilucoplan is a C5 inhibitor, not an FcRn blocker."],
 [4, "Myasthenic crisis is defined as worsening that requires:", ["A hospital admission", "A higher pyridostigmine dose", "IVIG", "Intubation, or non-invasive ventilation to avoid intubation"], 3, "Intubation defines MGFA class V; the 2016 consensus also counts non-invasive ventilation used to avoid intubation. Difficulty breathing or swallowing is an emergency."],
 [4, "The most common identified trigger of myasthenic crisis is:", ["Infection", "Surgery", "Pregnancy", "Exercise"], 0, "Infection caused 38% of crises in a 73-episode series; no trigger is found in 30-40%."],
 [4, "Which signs point to cholinergic rather than myasthenic crisis?", ["Dry mouth and dilated pupils", "Fever and rash", "Sweating, salivation, diarrhoea, slow heart rate and fasciculations", "High blood pressure alone"], 2, "These come from too much cholinesterase inhibitor. The label says the two may be hard to tell apart; cholinergic crisis is now rare."],
 [4, "The single breath count is done by:", ["Counting breaths per minute", "Taking a deep breath and counting aloud at about 2 counts per second", "Holding the breath as long as possible", "Counting pulse beats"], 1, "A count of 25 or more fits normal breathing muscles; each number matched about 116 mL of FVC."],
 [4, "A single breath count of 25 or more suggests:", ["Normal breathing-muscle function", "Imminent crisis", "Cholinergic toxicity", "Aspiration"], 0, "No MGFA class 1 patient counted under 25, and every class 3 patient failed to reach 25."],
 [4, "The 20/30/40 bedside rule (VC, MIP, MEP) originally comes from:", ["MG", "Asthma", "COPD", "Guillain-Barré syndrome"], 3, "No MG-specific validation of the full rule was found. In one 42-patient MG study, ventilation was unlikely with VC over 20 mL/kg, MEP over 40 cmH2O or MIP more negative than -40 cmH2O."],
 [4, "In neuromuscular breathing weakness, pulse oximetry:", ["Always falls first", "Can stay normal while CO2 is high", "Is the best early sign", "Measures vital capacity"], 1, "In one neuromuscular audit, 54% of patients with high CO2 had saturation of 95% or more."],
 [4, "Which antibiotic is contraindicated in MG on its label?", ["Amoxicillin", "Cephalexin", "Telithromycin", "Nitrofurantoin"], 2, "Telithromycin carried a boxed warning for fatal respiratory failure, sometimes within hours of the first dose. It is no longer marketed in the US."],
 [4, "Fluoroquinolones in MG:", ["Carry an FDA boxed warning for exacerbation of MG", "Have no warning", "Are the preferred antibiotics", "Are restricted only in children"], 0, "MG was added to the class boxed warning in February 2011."],
 [4, "For eclampsia in a woman with MG, the consensus guidance:", ["Recommends magnesium sulfate", "Recommends no treatment", "Recommends botulinum toxin", "Does not recommend magnesium sulfate; barbiturates or phenytoin usually suffice"], 3, "IV magnesium blocks neuromuscular transmission and has precipitated crises."],
 [4, "What does the MGFA say about drugs on its caution list?", ["They must never be given", "They are not necessarily off limits and may be necessary, with monitoring", "They are all safe", "They matter only in children"], 1, "Some listed drugs may be necessary and are used under clinician supervision."],
 [4, "Transient neonatal MG is caused by:", ["A gene from the father", "Breastfeeding", "A thymoma in the baby", "Maternal IgG antibodies crossing the placenta"], 3, "It affects about 10% of babies (9-13% in pooled series) and fades as maternal IgG is cleared."],
 [4, "Weakness in transient neonatal MG usually appears:", ["Within the first 24 hours", "At about 6 months", "At school age", "Only in premature babies"], 0, "It usually lasts up to 4 weeks and is most marked in the first week."],
 [4, "Which statement about pregnancy in MG is supported by pooled data?", ["Every woman worsens", "Pregnancy cures MG", "About 30% worsen in pregnancy and about 27% after delivery", "Pyridostigmine must be stopped"], 2, "Worsening is most often in the first trimester; the first months after delivery are the riskiest. Pyridostigmine is first-line in pregnancy."],
 [4, "UK hospital safety guidance treats pyridostigmine as:", ["An as-needed drug", "A time-critical medicine, given within 30 minutes of the due time", "A drug to stop on admission", "A night-only drug"], 1, "Late doses can cause weakness or inability to swallow; missed doses can precipitate crisis."],
 [4, "Under anaesthesia, people with MG are:", ["Resistant to non-depolarizing relaxants", "Unaffected by muscle relaxants", "More sensitive to non-depolarizing relaxants and resistant to succinylcholine", "Allergic to all anaesthetics"], 2, "Vecuronium ED95 was about 56% of normal; succinylcholine needs up to 2.6 times the usual dose."],
 [4, "A person with MG asks about the flu vaccine. A randomized trial of 47 AChR-MG patients found:", ["MG worsened in most", "Protection matched healthy controls and MG did not worsen", "AChR antibodies doubled", "The vaccine did not work"], 1, "Inactivated vaccines are considered safe in MG; guidance says live vaccines should be avoided if possible under immunosuppression."],
 [4, "Checkpoint-inhibitor-related MG typically begins:", ["Years after treatment", "Before the drug is given", "Only after the drug is stopped", "A median of about 4 weeks after starting"], 3, "In 65 cases, 37% also had myositis and 38% died (23% from MG)."],
 [4, "Which cell therapy in MG has a completed double-blind placebo-controlled trial?", ["Anti-CD19 CAR-T (KYV-101)", "MuSK-CAART", "mRNA anti-BCMA CAR-T (Descartes-08)", "Autologous stem cell transplant"], 2, "Phase 2b, n=26: 66.7% vs 27.3% reached the MG Composite responder endpoint. Its phase 3 (AURORA) is under way."],
 [4, "Autologous stem cell transplant gave drug-free remission in 89% of evaluable people with severe refractory MG, but:", ["Had no serious risks", "Required infusions every month", "Worked only in ocular MG", "Had 9.5% transplant-related mortality at 100 days"], 3, "Evidence level: early evidence, from a 21-patient retrospective series with a median follow-up of 6.7 years."],
 [4, "Which symptom in a person with MG needs emergency help?", ["New difficulty breathing or swallowing", "Mild eyelid droop in the evening", "Occasional double vision when tired", "Tiredness after exercise"], 0, "Crisis usually builds up over time, which leaves a window to act. Breathing or swallowing difficulty is an emergency."],
 [4, "What does published guidance say about breastfeeding with MG?", ["It is never allowed", "It is encouraged; pyridostigmine, prednisolone and azathioprine are not contraindications", "It is possible only with IVIG", "It causes neonatal MG"], 1, "Breastfeeding is advised against with cyclophosphamide, mycophenolate or methotrexate. The ravulizumab label advises stopping during treatment."],
 [5, "Who gave the first recognisable account of MG, in 1672?", ["Samuel Wilks", "Wilhelm Erb", "Thomas Willis", "Friedrich Jolly"], 2, "Willis described patients well in the morning and weak by noon. The account went largely unnoticed until 1903."],
 [5, "Who coined myasthenia gravis pseudoparalytica in 1895?", ["Friedrich Jolly", "Samuel Goldflam", "Mary Walker", "John Simpson"], 0, "Jolly also showed that repeated electrical stimulation made the muscle response decline, the forerunner of RNS."],
 [5, "In 1934 Mary Walker reported dramatic improvement with:", ["Prednisone", "Thymectomy", "Plasma exchange", "Physostigmine"], 3, "She reported neostigmine in 1935, the start of cholinesterase-inhibitor treatment."],
 [5, "Who proposed in 1960 that MG is autoimmune, caused by antibodies to the endplate receptor?", ["Alfred Blalock", "John Simpson", "Jon Lindstrom", "Daniel Drachman"], 1, "Simpson also suggested a role for the thymus."],
 [5, "The 1973 experiment of Patrick and Lindstrom showed that:", ["Immunising rabbits with purified AChR causes myasthenic paralysis", "Thymectomy cures MG", "MuSK antibodies cause MG", "Edrophonium worsens MG"], 0, "The paralysis reversed with anticholinesterases: the experimental autoimmune MG (EAMG) model."],
 [5, "MuSK antibodies were discovered in:", ["1934", "1976", "2001", "2017"], 2, "Hoch and colleagues found them in 70% of AChR-seronegative generalized MG."],
 [5, "MG mortality fell from about 40% to about 5% between the early 1960s and the 1970s mainly because of:", ["Thymectomy", "Rituximab", "FcRn blockers", "Positive-pressure ventilation and intensive care"], 3, "Deymeer's history review credits ventilation and ICUs."],
 [5, "The first randomized trial showing a benefit of thymectomy (MGTX) was published in:", ["1939", "1976", "2000", "2016"], 3, "About 75 years after Blalock. Earlier evidence was retrospective, with inconsistent definitions."],
 [5, "The first complement inhibitor approved by the FDA for gMG, in 2017, was:", ["Efgartigimod", "Eculizumab", "Zilucoplan", "Rituximab"], 1, "Approved on 23 October 2017 for AChR-antibody-positive adults. Efgartigimod, in 2021, was the first FcRn blocker."],
 [5, "Lindstrom's 1976 radioimmunoassay found AChR antibodies in:", ["17% of patients", "All controls tested", "87% of 71 patients and none of 175 controls", "Only ocular patients"], 2, "This established the diagnostic assay."],
 [5, "Passive transfer of MG patients' immunoglobulin to mice (Toyka 1975) showed that:", ["MG is inherited", "The antibody alone can reproduce MG features", "The thymus is not involved", "Pyridostigmine causes MG"], 1, "Treated mice had smaller mEPPs, fewer AChRs and, in some, a decrement on RNS that reversed with neostigmine."],
 [5, "Blalock's 1939 report described:", ["Removal of a thymic tumour from a patient with MG", "Discovery of AChR antibodies", "The first FcRn blocker", "Edrophonium testing"], 0, "The operation took place in 1936. Sauerbruch had removed thymus tissue in an MG patient in 1911."]
];
inits.quiz=()=>{
  const F=[['mix','%t:quiz.mixed%'],...Object.keys(PARTN).map(k=>[k,'%t:part%'+k])];
  $('#qFilter').innerHTML=F.map(([k,l])=>`<button class="btn" data-qf="${k}" aria-pressed="${k==='mix'}">${l}</button>`).join('');
  let list=[],i=0,score=0,missed=[],answered=false;
  function start(k){const r=rng(Date.now()%1e6);let L=QZ.filter(q=>k==='mix'||String(q[0])===k).slice();for(let a=L.length-1;a>0;a--){const j=Math.floor(r()*(a+1));[L[a],L[j]]=[L[j],L[a]]}
    list=k==='mix'?L.slice(0,20):L;i=0;score=0;missed=[];q()}
  function q(){answered=false;$('#qBar').style.width=(i/list.length*100)+'%';
    if(i>=list.length){const pct=Math.round(score/list.length*100);
      $('#qCard').innerHTML=`<div class="kicker">%t:quiz.finished%</div><div class="q">%t:quiz.scored{score:score,total:list.length,pct:pct}%</div><p>${pct>=85?'%t:quiz.excellent%':pct>=65?'%t:quiz.solid%':'%t:quiz.retry%'}</p>`+
       (missed.length?`<dl class="kv">${missed.map(m=>`<div><dt>${m[1]}</dt><dd><b>${m[2][m[3]]}.</b> ${m[4]}</dd></div>`).join('')}</dl>`:'')+`<div class="ctrls"><button class="btn primary" id="qAgain">%t:quiz.again%</button><button class="btn" data-go="review">%t:quiz.to_cards%</button></div>`;
      $('#qAgain').onclick=()=>start($('[data-qf][aria-pressed="true"]').dataset.qf);return}
    const Q=list[i];
    $('#qCard').innerHTML=`<div class="readout"><span>%t:quiz.question{n:i+1,total:list.length}%</span><span>%t:quiz.score% <b>${score}</b></span><span>${PARTN[Q[0]]}</span></div><div class="q">${Q[1]}</div><div class="opts">${Q[2].map((o,j)=>`<button class="opt" data-o="${j}"><span class="l">${'%t:quiz.letters%'[j]}</span><span>${o}</span></button>`).join('')}</div><div id="qFb"></div>`;
  }
  $('#qCard').addEventListener('click',e=>{const b=e.target.closest('.opt');if(b&&!answered){answered=true;const Q=list[i],j=+b.dataset.o,ok=j===Q[3];if(ok)score++;else missed.push(Q);
      $$('.opt',$('#qCard')).forEach((o,k)=>{o.disabled=true;if(k===Q[3])o.classList.add('right');else if(k===j)o.classList.add('wrong')});
      $('#qFb').innerHTML=`<div class="expl"><b style="color:var(${ok?'--good':'--bad'})">${ok?'%t:quiz.correct%':'%t:quiz.wrong%'}</b> ${Q[4]}</div><div class="ctrls" style="margin-top:12px"><button class="btn primary" id="qNext">${i+1<list.length?'%t:quiz.next%':'%t:quiz.results%'}</button></div>`;
      $('#qNext').onclick=()=>{i++;q()};$('#qNext').focus({preventScroll:true})}});
  $('#qFilter').addEventListener('click',e=>{const b=e.target.closest('[data-qf]');if(!b)return;$$('[data-qf]').forEach(x=>x.setAttribute('aria-pressed',x===b));start(b.dataset.qf)});
  start('mix');
};

/* =============== 5.4 glossary =============== */
const GL=[
 ["Acetylcholine (ACh)", "The transmitter the motor nerve releases at the junction. Each vesicle holds a quantum of about 10,000 molecules; two ACh molecules must bind to open one receptor.", "nmj"],
 ["Acetylcholine receptor (AChR)", "The ion channel on the muscle side of the junction that opens when ACh binds. A five-subunit protein (adult form α2βδε), packed on the crests of the junctional folds. The main target of MG antibodies.", "nmj"],
 ["Acetylcholinesterase (AChE)", "The enzyme in the synaptic cleft that breaks down ACh, ending each signal within about a millisecond. Pyridostigmine inhibits it.", "nmj"],
 ["Agrin", "A protein released by the motor nerve that binds LRP4 and switches on MuSK, starting the signal that clusters AChRs under the nerve.", "nmj"],
 ["Amifampridine (3,4-DAP)", "A potassium-channel blocker, US-labelled for Lambert-Eaton syndrome, not MG; in IMPACT-MG it did not beat placebo as an add-on in AChR-MG.", "pyrido"],
 ["Aminoglycosides", "Antibiotics such as gentamicin and tobramycin. Labels warn of curare-like effects at the junction and advise caution in MG.", "drugs"],
 ["Antigenic modulation", "Loss of receptors because antibodies cross-link neighbouring AChRs, which are then internalised and degraded about three times faster than normal.", "antibodies"],
 ["Arthrogryposis (FARAD)", "Joint contractures present at birth. Maternal antibodies against the fetal form of the AChR can restrict movement in the womb; the umbrella term is fetal AChR antibody-related disorders (FARAD).", "nursing"],
 ["Atropine", "An antimuscarinic drug. The pyridostigmine label says it can counter muscarinic side effects but may mask signs of overdose and an unnoticed cholinergic crisis.", "pyrido"],
 ["Autoantibody", "An antibody that targets the body's own tissue. In MG the main targets are AChR, MuSK and LRP4.", "antibodies"],
 ["Autologous HSCT", "Autologous haematopoietic stem cell transplantation: high-dose conditioning wipes out the immune repertoire and the person's own stem cells rebuild it. Early evidence in severe refractory MG, with 9.5% transplant-related mortality at 100 days in the largest series.", "cure"],
 ["Azathioprine", "An oral steroid-sparing immunosuppressant. First response after 4-10 months. The Nordic guidance advises testing TPMT activity before starting, because low activity risks severe marrow toxicity.", "ladder"],
 ["BCMA", "B-cell maturation antigen, a surface marker of plasmablasts and plasma cells, the cells that make antibodies. The target of Descartes-08 and dual BCMA/CD19 CAR-T.", "cure"],
 ["BiPAP / NIV", "Non-invasive ventilation through a mask. In one series it avoided intubation in about 58% of crises where it was the first support; a PaCO2 above 45 mmHg at the start predicted failure.", "crisis"],
 ["Botulinum toxin", "A neurotoxin injected for blepharospasm, dystonia and cosmetic use. Labels carry a boxed warning for distant spread and advise monitoring in MG; it raises jitter for 6 months or more.", "drugs"],
 ["Botulism", "Poisoning by botulinum toxin: acute, symmetric paralysis descending from the cranial nerves in an alert, afebrile person, sometimes with dilated pupils. An MG mimic.", "ddx"],
 ["Bulbar weakness", "Weakness of the muscles for speaking, chewing and swallowing (controlled from the brainstem, or bulb). The main first symptom in up to 15% of people with MG.", "what"],
 ["C5", "Complement component 5, the last common step before the membrane attack complex forms. The target of eculizumab, ravulizumab, zilucoplan and newer agents.", "biologics"],
 ["CAR-T cell therapy", "T cells engineered with a chimeric antigen receptor that makes them kill cells bearing a chosen marker, such as CD19 or BCMA. Early evidence in MG from small series and one small randomized trial.", "cure"],
 ["Cell-based assay (CBA)", "An antibody test using cells that display the target protein in its natural form, for example clustered AChR with rapsyn. It finds antibodies that standard assays miss.", "dx"],
 ["Checkpoint-inhibitor MG", "MG triggered or worsened by cancer immunotherapy that blocks PD-1, PD-L1 or CTLA-4. Median onset about 4 weeks; in a 65-patient series 37% also had myositis and 8% myocarditis.", "drugs"],
 ["Cholinergic crisis", "Weakness from too much cholinesterase inhibitor, with muscarinic signs (sweating, salivation, diarrhoea, slow heart) and fasciculations. Now rare, and hard to tell from myasthenic crisis by symptoms alone.", "crisis"],
 ["CMAP", "Compound muscle action potential: the summed electrical response of a muscle to a nerve stimulus, measured in nerve conduction and RNS studies.", "dx"],
 ["Cogan's lid twitch", "A brief upward twitch of the eyelid seen on eye examination, a bedside sign of MG. Across 7 studies its sensitivity was 50-99% and specificity 75-100%.", "dx"],
 ["ColQ", "The collagen tail that anchors acetylcholinesterase to the basal lamina of the cleft. Without it, mice have no AChE at the junction.", "nmj"],
 ["Complement", "A cascade of blood proteins that can punch holes in membranes. In AChR-MG, antibody-bound receptors trigger the classical pathway and the membrane attack complex destroys the junctional folds.", "antibodies"],
 ["Complete stable remission (CSR)", "MGFA post-intervention status: no symptoms or signs of MG for at least 1 year, with no MG therapy during that time.", "classes"],
 ["Congenital myasthenic syndromes (CMS)", "Inherited, non-autoimmune disorders of the junction caused by variants in 32 known genes. Onset is usually from birth to childhood, antibodies are negative, and immunotherapy does not help.", "ddx"],
 ["Corticosteroids", "Prednisone or prednisolone: the usual first immunosuppressant in MG. They can cause early transient worsening, and long-term use brings bone, glucose and infection risks.", "ladder"],
 ["CPEO", "Chronic progressive external ophthalmoplegia, usually mitochondrial: slowly progressive, symmetric eye-movement weakness with little double vision and no fluctuation.", "ddx"],
 ["Cytokine release syndrome (CRS)", "A systemic inflammatory reaction after CAR-T infusion, with fever and sometimes low blood pressure. In MG series it has been mainly grade 1-2.", "cure"],
 ["D-penicillamine", "A drug that can induce true AChR-antibody MG in up to 7% of treated patients, usually mild and ocular, often remitting within a year of stopping.", "drugs"],
 ["Decrement", "The fall in CMAP amplitude across a train of nerve stimuli. A reproducible decrement of 10% or more at 2-5 Hz supports MG.", "dx"],
 ["Diplopia", "Double vision from weak, misaligned eye muscles. With ptosis, the most common first symptom of MG.", "what"],
 ["Dok-7", "A cytoplasmic adaptor protein that carries the MuSK signal; mice without it form no AChR clusters or neuromuscular synapses.", "nmj"],
 ["Double-seronegative MG", "MG with neither AChR nor MuSK antibodies, about 6-10% of MG. Some patients have LRP4 or clustered-AChR antibodies.", "antibodies"],
 ["Early-onset MG", "MG beginning before age 50. Linked to thymic hyperplasia and, in people of European descent, the HLA A1-B8-DR3 haplotype.", "what"],
 ["Eculizumab", "An IV monoclonal antibody against C5, approved by the FDA in 2017 for AChR-antibody-positive gMG; the first complement inhibitor for MG.", "biologics"],
 ["Edrophonium (Tensilon) test", "An IV test with a very short-acting cholinesterase inhibitor. Rarely used now because mimics test positive and it carries cardiac risks.", "dx"],
 ["Efgartigimod", "An FcRn blocker given IV or SC in 4-week cycles. Approved in the US in 2021 (AChR+) and widened in May 2026 to adults with gMG regardless of antibody status.", "biologics"],
 ["Endplate potential (EPP)", "The local depolarisation of the endplate after one nerve impulse. If it reaches threshold it fires a muscle action potential; in MG many EPPs fall short.", "nmj"],
 ["Experimental autoimmune MG (EAMG)", "The animal model in which immunising an animal with purified AChR causes myasthenic weakness; first shown in rabbits in 1973.", "history"],
 ["Extended transsternal thymectomy", "Removal of the thymus and surrounding fat through a split breastbone, taking about 85-95% of thymic tissue. The operation tested in MGTX.", "thymectomy"],
 ["Fab-arm exchange", "The swapping of half-molecules between IgG4 antibodies, which makes most MuSK IgG4 bispecific and functionally monovalent, unable to cross-link its target.", "antibodies"],
 ["Fatigability", "Weakness that builds with repeated or sustained use and eases with rest: the hallmark of MG, as distinct from general tiredness (fatigue).", "fatigue"],
 ["Fatigue", "A feeling of tiredness or lack of energy, separate from muscle fatigability. Reported by about 60% of people with MG.", "fatigue"],
 ["FcRn", "The neonatal Fc receptor, which rescues IgG from breakdown inside cells and recycles it, giving IgG a half-life of about 19-21 days.", "biologics"],
 ["FcRn blocker", "A drug that occupies FcRn so IgG, including pathogenic antibodies, is degraded. Total IgG falls by about 55-80% and recovers after dosing stops: efgartigimod, rozanolixizumab, nipocalimab.", "biologics"],
 ["Fluoroquinolones", "Antibiotics such as ciprofloxacin and levofloxacin. They carry an FDA boxed warning for exacerbation of MG.", "drugs"],
 ["Generalized MG (gMG)", "MG affecting muscles beyond the eyes: bulbar, neck, limb or breathing muscles (MGFA class II-V).", "what"],
 ["IgG1 and IgG3", "IgG subclasses that activate complement. Most AChR antibodies belong to them, which is why complement drives damage in AChR-MG.", "antibodies"],
 ["IgG4", "An IgG subclass that does not activate complement and undergoes Fab-arm exchange. Most MuSK antibodies are IgG4.", "antibodies"],
 ["Impending crisis", "Rapid worsening of MG that, in the treating physician's opinion, could lead to crisis within days to weeks (2016 consensus).", "crisis"],
 ["Inebilizumab", "An anti-CD19 B-cell-depleting antibody given IV every 6 months after two loading doses. FDA-approved in December 2025 for AChR+ or MuSK+ gMG.", "biologics"],
 ["Inspiratory muscle training", "Breathing exercises against a resistance. In a 27-person randomized trial in MG it improved inspiratory and expiratory pressures but not lung volumes.", "living"],
 ["IVIG", "Intravenous immunoglobulin: pooled donor IgG used as a fast-acting treatment in exacerbations and before surgery. Boxed warning for thrombosis and kidney injury.", "ladder"],
 ["Jitter", "Variation in the timing of the muscle response between two fibres of one motor unit, measured by single-fibre or concentric-needle EMG. The most sensitive test for MG, but not specific.", "dx"],
 ["Juvenile MG", "MG beginning before age 18, about 10% of cases. Ocular forms and spontaneous remission are more common in pre-pubertal children.", "what"],
 ["Lambert-Eaton myasthenic syndrome (LEMS)", "An autoimmune disease of the nerve terminal with antibodies to P/Q calcium channels. Proximal leg weakness, dry mouth, low reflexes, and a CMAP that increments after exercise; about half have small-cell lung cancer.", "ddx"],
 ["Late-onset MG", "MG beginning at age 50 or later. Its incidence is rising, mainly in men, and titin antibodies are more common (58% vs 10% in early-onset MG).", "what"],
 ["Live vaccine", "A vaccine containing a weakened living organism. Guidance says to avoid it if possible under immunosuppression, and FcRn blocker labels advise against it during treatment; inactivated and subunit vaccines are considered safe in MG.", "living"],
 ["LRP4", "Low-density lipoprotein receptor-related protein 4, the agrin receptor that activates MuSK. LRP4 antibodies (mainly IgG1) are found in some double-seronegative MG.", "nmj"],
 ["Magnesium sulfate", "An IV drug that blocks neuromuscular transmission. The consensus does not recommend it for eclampsia in MG.", "drugs"],
 ["Main immunogenic region (MIR)", "A site at the top of the AChR α1 subunit that half or more of MG antibodies bind.", "antibodies"],
 ["Membrane attack complex (MAC)", "C5b-9, the pore-forming end product of complement. It is found at endplates in MG biopsies, where it destroys the junctional folds.", "antibodies"],
 ["Meningococcal vaccination", "Vaccination against Neisseria meningitidis serogroups A, C, W, Y and B, required by labels at least 2 weeks before a C5 inhibitor because C5 blockade raises meningococcal infection risk.", "biologics"],
 ["MG Composite", "A 10-item scale with weighted scoring, maximum 50. A 3-point improvement signified clinical improvement in validation.", "classes"],
 ["MG-ADL", "Myasthenia Gravis Activities of Daily Living: 8 patient-reported items, each 0-3, total 0-24. A 2-point improvement indicates clinical improvement.", "classes"],
 ["MG-QOL15r", "The revised 15-item MG quality-of-life questionnaire with a 3-response format, the preferred MG quality-of-life instrument.", "classes"],
 ["MGFA clinical classification", "The Myasthenia Gravis Foundation of America classes I (ocular only) to V (intubated), with a and b subtypes for limb or bulbar predominance.", "classes"],
 ["MGFA post-intervention status (MGFA-PIS)", "Categories for the state of MG after treatment: complete stable remission, pharmacologic remission, minimal manifestations, improved, unchanged, worse, exacerbation, died of MG.", "classes"],
 ["MGTX", "The randomized trial (126 people, AChR+ non-thymomatous generalized MG, aged 18-65) showing that extended transsternal thymectomy plus prednisone beat prednisone alone over 3 and 5 years.", "thymectomy"],
 ["Miller Fisher syndrome", "Acute eye-muscle paralysis with ataxia and lost reflexes in a fully conscious person; anti-GQ1b antibodies in 83% and raised CSF protein without cells in 76%.", "ddx"],
 ["Miniature endplate potential (mEPP)", "The small depolarisation (about 1 mV) from the spontaneous release of a single quantum. mEPPs are smaller in MG because receptors are lost.", "nmj"],
 ["Minimal manifestations (MM)", "No symptoms of functional limitation from MG, though some weakness can be found on examination (MGFA wording). MM or better is the 2016 consensus treatment goal.", "classes"],
 ["Minimal symptom expression (MSE)", "An MG-ADL score of 0 or 1, used as an endpoint in recent trials.", "classes"],
 ["Muscarinic effects", "Cholinesterase-inhibitor side effects on glands and smooth muscle: nausea, diarrhoea, cramps, salivation, bronchial secretions, sweating, small pupils.", "pyrido"],
 ["MuSK", "Muscle-specific kinase, the receptor tyrosine kinase that, once activated by agrin and LRP4, clusters AChRs. MuSK antibodies cause about 7-10% of MG.", "antibodies"],
 ["MuSK-CAART", "T cells engineered to display the MuSK protein, so they kill only B cells that make anti-MuSK antibodies. A completed phase 1 (7 participants) has no published outcomes yet.", "cure"],
 ["Myasthenia gravis", "An autoimmune disease in which antibodies against AChR, MuSK or related proteins at the neuromuscular junction cause fluctuating, fatigable muscle weakness.", "what"],
 ["Myasthenic crisis", "Worsening of MG that needs intubation, or non-invasive ventilation to avoid intubation (MGFA class V). Lifetime risk about 15-20%.", "crisis"],
 ["Mycophenolate mofetil", "An oral steroid-sparing immunosuppressant. Two 2008 trials were negative, but it is widely used; contraindicated in pregnancy (boxed warning for embryofetal toxicity).", "ladder"],
 ["Neostigmine", "A short-acting cholinesterase inhibitor, used by injection when oral pyridostigmine cannot be given (60 mg oral pyridostigmine is about 1-1.5 mg IM or SC neostigmine).", "pyrido"],
 ["Neuromuscular junction (NMJ)", "The synapse where a motor nerve terminal meets a muscle fibre: nerve terminal, a 50-100 nm cleft, and the folded endplate.", "nmj"],
 ["Nicotinic effects", "Cholinesterase-inhibitor side effects at the junction itself: muscle cramps, fasciculations and, with excess, weakness.", "pyrido"],
 ["Nipocalimab", "An IV anti-FcRn antibody given every 2 weeks, FDA-approved in April 2025 for AChR+ or MuSK+ gMG from age 12.", "biologics"],
 ["Non-depolarizing neuromuscular blockers", "Muscle relaxants such as rocuronium and vecuronium. People with MG are more sensitive to them (vecuronium ED95 about 56% of normal); an anaesthesia review says they should be given in smaller doses with monitoring.", "drugs"],
 ["Obstructive sleep apnoea", "Repeated collapse of the upper airway during sleep. Found in 36% of people with MG in one study, against an expected 15-20% in the general population.", "living"],
 ["Ocular MG", "MG limited to the eyelid and eye muscles (MGFA class I). Of people still purely ocular after 2 years, about 90% stay ocular.", "what"],
 ["OPMD", "Oculopharyngeal muscular dystrophy: an inherited (autosomal dominant) disease usually starting in the sixth decade with ptosis and difficulty swallowing; a PABPN1 repeat expansion.", "ddx"],
 ["Passive transfer", "Injecting a patient's antibodies into an animal to see whether they reproduce the disease. Done for MG in 1975, showing the antibody alone is enough.", "history"],
 ["Pharmacologic remission", "MGFA-PIS: the same criteria as complete stable remission, but the person still takes some MG therapy (not cholinesterase inhibitors).", "classes"],
 ["Plasma exchange (PLEX)", "Removal of the person's plasma, and with it circulating antibodies: a fast-acting treatment for crisis and severe worsening. The 2016 consensus says it cannot be used in sepsis.", "ladder"],
 ["Postsynaptic folds", "Deep infoldings of the endplate membrane, up to about 1 µm deep in humans. AChRs line the crests; sodium channels line the troughs. Complement destroys them in MG.", "nmj"],
 ["Ptosis", "A drooping upper eyelid. It worsens with sustained upgaze in MG and is the most common first symptom.", "what"],
 ["Pyridostigmine", "The standard oral cholinesterase inhibitor for MG symptoms (Mestinon). Each dose acts for about 3-4 hours.", "pyrido"],
 ["QMG", "Quantitative Myasthenia Gravis score: 13 clinician-scored items, each 0-3, total 0-39.", "classes"],
 ["Quantal content", "The number of quanta released by one nerve impulse: about 20-30 at a human junction.", "nmj"],
 ["Quantum", "The packet of transmitter in one synaptic vesicle: about 10,000 ACh molecules.", "nmj"],
 ["Radioimmunoassay (RIPA)", "The standard blood test that measures AChR or MuSK antibodies binding a radio-labelled antigen in solution.", "dx"],
 ["Rapsyn", "A protein under the membrane that tethers AChRs into dense clusters; without it, no AChR clusters form.", "nmj"],
 ["Ravulizumab", "A long-acting IV C5 inhibitor given every 8 weeks, FDA-approved in 2022 for AChR+ gMG.", "biologics"],
 ["Readily releasable pool", "The vesicles docked and ready to release; it empties during a train of impulses, causing rundown until reserve vesicles refill it after 1-2 seconds.", "fatigue"],
 ["Refractory MG", "MGFA-PIS unchanged or worse after corticosteroids and at least two other immunosuppressants at adequate dose and duration, with persistent symptoms or limiting side effects.", "classes"],
 ["REMS", "Risk Evaluation and Mitigation Strategy: the US controlled-access programme for C5 inhibitors, with a patient safety card listing meningococcal warning signs.", "biologics"],
 ["Repetitive nerve stimulation (RNS)", "Stimulating a nerve several times at 2-5 Hz while recording the muscle response; a decrement of 10% or more supports MG.", "dx"],
 ["Rituximab", "An anti-CD20 antibody that depletes B cells. Strongest evidence in MuSK-MG; in new-onset AChR+ gMG, RINOMAX favoured it.", "ladder"],
 ["Rozanolixizumab", "A subcutaneous anti-FcRn antibody given weekly for 6 weeks per cycle, approved for AChR+ or MuSK+ gMG. Headache is common.", "biologics"],
 ["Ryanodine receptor antibodies", "Antibodies to the calcium-release channel inside muscle, found mainly in thymoma and late-onset MG, linked to more severe disease.", "antibodies"],
 ["Safety factor", "The ratio of the endplate potential to the depolarisation needed to fire the muscle: normally 2-4 times what is needed. MG lowers it towards 1.", "nmj"],
 ["Seronegative MG", "MG without detectable AChR antibodies on the standard assay. MuSK, LRP4 or clustered-AChR antibodies explain some cases.", "antibodies"],
 ["Single breath count", "A bedside test: a deep breath, then counting aloud at about 2 per second. A count of 25 or more fits normal breathing-muscle function.", "crisis"],
 ["Single-fibre EMG (SFEMG)", "A needle EMG technique that measures jitter and blocking between muscle fibres of one motor unit.", "dx"],
 ["Steroid dip", "Transient worsening of MG soon after corticosteroids are started, reported in about 21-48% of patients. No source gives a typical timing; studies used 2-week and 4-week windows.", "ladder"],
 ["Succinylcholine", "A depolarizing muscle relaxant. People with MG are resistant to it, needing up to about 2.6 times the usual dose.", "nursing"],
 ["Sugammadex", "A drug that reverses neuromuscular block after surgery. A 24-study review in MG found fast reversal and low postoperative crisis rates.", "nursing"],
 ["Synaptic cleft", "The 50-100 nm gap between nerve terminal and muscle, filled with basal lamina that holds acetylcholinesterase.", "nmj"],
 ["Telithromycin", "A ketolide antibiotic contraindicated in MG after fatal respiratory failure, sometimes within hours of the first dose; no longer marketed in the US.", "drugs"],
 ["Thymectomy", "Surgical removal of the thymus. In MGTX it improved strength and reduced steroid needs in AChR+ generalized MG; current evidence does not support it in MuSK-MG.", "thymectomy"],
 ["Thymic hyperplasia", "An enlarged thymus with lymphoid follicles and germinal centres, seen in about 65% of people with MG, mainly early-onset.", "thymectomy"],
 ["Thymoma", "A tumour of thymic epithelial cells, present in about 10-20% of people with MG; about 30-44% of people with thymoma have MG. The 2016 consensus says that, with rare exceptions, people with MG and thymoma should have surgery.", "thymectomy"],
 ["Thymus", "An organ behind the breastbone where T cells learn tolerance to the body's own proteins. Changes in it are thought to start the AChR immune response in early-onset MG.", "thymectomy"],
 ["Time-critical medicine", "A drug whose late or missed dose can cause harm. UK safety bulletins class pyridostigmine this way, to be given within 30 minutes of the due time.", "nursing"],
 ["Titin antibodies", "Antibodies to the giant muscle protein titin, found in about 95% of thymoma-MG. Their presence in a person under 60 strongly suggests thymoma.", "antibodies"],
 ["TPMT", "Thiopurine methyltransferase, an enzyme that handles azathioprine. Low or absent activity risks severe bone-marrow toxicity, so guidance advises testing it before treatment.", "ladder"],
 ["Transient neonatal MG", "Temporary weakness in a newborn caused by maternal antibodies crossing the placenta: about 10% of babies, usually appearing in the first 24 hours and resolving within 4 weeks.", "nursing"],
 ["U-shaped decrement", "The RNS pattern in MG: the biggest fall between the 1st and 2nd responses, a low point at the 4th-5th, then partial recovery.", "dx"],
 ["Vital capacity (VC)", "The largest volume of air a person can breathe out after a full breath in. In MG, ventilation was unlikely when VC stayed above 20 mL/kg.", "crisis"],
 ["Zilucoplan", "A small subcutaneous peptide C5 inhibitor self-injected once daily. Approved in 2023 for AChR+ gMG; MG-ADL responders 73.1% vs 46.1% at week 12.", "biologics"]
];
inits.glossary=()=>{
  const inp=$('#glSearch');const tname=id=>{const m=MODS.find(x=>x.id===id);return m?m.t:''};
  function render(){const q=inp.value.trim().toLowerCase();const L=GL.filter(g=>!q||g[0].toLowerCase().includes(q)||g[1].toLowerCase().includes(q));
    $('#glList').innerHTML=L.map(g=>`<div><b>${g[0]}</b>${g[1]} <button class="btn ghost" style="padding:3px 9px;font-size:12px;margin-top:6px" data-go="${g[2]}">→ ${tname(g[2])}</button></div>`).join('')||'<p>%t:glossary.none%</p>';
    $('#glCount').textContent=`%t:glossary.count{n:L.length,total:GL.length}%`}
  inp.addEventListener('input',render);render();
};

/* =============== 5.5 sources =============== */
const AREAN={A:'Epidemiology, clinical picture & history',B:'Junction & immunopathology',C:'Diagnosis & differential',D:'Conventional therapy',E:'Thymus & thymectomy',F:'Biologics',G:'Crisis & drugs to avoid',H:'Nursing & living',I:'Research & cure'};
inits.sources=()=>{
  let area='all';const inp=$('#srcSearch');
  $('#srcFilter').innerHTML=[['all','%t:sources.all%']].concat(Object.entries(AREAN)).map(([k,l])=>`<button class="btn" data-sa="${k}" aria-pressed="${k==='all'}">${l}</button>`).join('');
  const esc=s=>s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  function render(){const q=inp.value.trim().toLowerCase();let n=0;
    $('#srcList').innerHTML=SOURCES.map((s,i)=>{const show=(area==='all'||s.areas.includes(area))&&(!q||s.text.toLowerCase().includes(q)||s.key.toLowerCase().includes(q));if(!show)return'';n++;
      return `<li id="src-${s.key}" value="${i+1}"><span class="key">[${i+1}] ${esc(s.key)}${s.aliases?'%t:sources.also%'+s.aliases.map(esc).join(', '):''}</span><span>${esc(s.text)}</span>${s.link?`<a href="${esc(s.link)}" target="_blank" rel="noopener">${esc(s.link)}</a>`:''}${s.note?`<span class="srcnote">${esc(s.note)}</span>`:''}<span class="mods">${s.areas.map(a=>`<span class="tag nerve">${AREAN[a]}</span>`).join('')}${s.unverified?'<span class="tag warn">%t:sources.check%</span>':''}</span></li>`}).join('');
    $('#srcCount').textContent=`%t:sources.count{n:n,total:SOURCES.length}%`}
  inp.addEventListener('input',render);
  $('#srcFilter').addEventListener('click',e=>{const b=e.target.closest('[data-sa]');if(!b)return;area=b.dataset.sa;$$('[data-sa]').forEach(x=>x.setAttribute('aria-pressed',x===b));render()});
  render();
};
onShow.sources=()=>{const inp=$('#srcSearch');if(inp&&inp.value){inp.value='';inp.dispatchEvent(new Event('input'))}
  if($('[data-sa="all"]')&&$('[data-sa="all"]').getAttribute('aria-pressed')!=='true')$('[data-sa="all"]').click()};
